import csv,collections
rows=list(csv.DictReader(open('responses.csv')))
c=collections.defaultdict(list)
for r in rows: c[(r['number_set'],int(r['target']))].append(int(r['rating']))
agg=collections.defaultdict(list)
for (s,t),v in c.items():
  ex=[int(x) for x in s.split(',')]
  if t in ex: continue
  pos='below' if t<min(ex) else ('above' if t>max(ex) else 'in')
  n=len(ex)
  agg[(min(n,3),pos)].append(sum(v)/len(v))
  if n>=2: agg[('all',pos)].append(sum(v)/len(v))
for k in sorted(agg,key=str): print(k,len(agg[k]),round(sum(agg[k])/len(agg[k]),3))
# shared digit sets
for (s,t),v in sorted(c.items()):
  ex=[int(x) for x in s.split(',')]
  if len(ex)>=3 and len({e%10 for e in ex})==1 and t not in ex and t%10==ex[0]%10:
    print(s,t,round(sum(v)/len(v),2), 'out' if (t<min(ex) or t>max(ex)) else 'in')
"

